mapper.select:
SELECT * FROM resume_dispatch WHERE resume_id IN
#{resumeId}
ORDER BY dispatch_id DESC

mapper.update:
UPDATE resume_dispatch
SET dispatch_status = #{dispatchStatus},
    confirm_time = #{confirmTime},
    update_time = NOW(),
    update_user_id = #{updateUserId},
    update_user_name = #{updateUserName}
WHERE resume_id = #{resumeId}
  AND interviewer_id = #{interviewerId}
